INSERT INTO `messages` (`id`, `from_user_id`, `to_user_id`, `message`, `is_read`, `created_at`) VALUES
(1, 12, 22, 'Доброго дня! Хочу записатись на лазерну епіляцію. Підкажіть вільний час.', 1, '2026-05-01 06:15:00'),
(2, 22, 12, 'Доброго дня! Вільний час є у вівторок о 10:00 або в середу о 14:00. Який вам зручніше?', 1, '2026-05-01 06:45:00'),
(3, 12, 22, 'Дякую! Запишіть мене на вівторок 10:00.', 1, '2026-05-01 07:00:00'),
(4, 12, 22, 'Підкажіть, чи можна перенести запис?', 1, '2026-05-03 08:20:00'),
(5, 22, 12, 'Так, можна. На яку дату бажаєте перенести?', 0, '2026-05-03 09:00:00'),
(6, 42, 22, 'Цікавить консультація дерматолога. Коли можна прийти?', 1, '2026-05-02 07:30:00'),
(7, 22, 42, 'Консультація доступна в четвер або п\'ятницю з 14:00 до 17:00.', 1, '2026-05-02 08:00:00'),
(8, 42, 22, 'Запишіть на четвер 15:00. Дякую!', 0, '2026-05-03 05:00:00'),
(9, 11, 22, 'Чи є знижки на мезотерапію для постійних клієнтів?', 1, '2026-05-02 11:20:00'),
(10, 22, 11, 'Для постійних клієнтів діє знижка 10%. Для запису натисніть кнопку \"Записатися\".', 0, '2026-05-03 06:30:00'),
(11, 6, 23, 'Після процедури залишилось почервоніння. Це нормально?', 1, '2026-05-02 13:00:00'),
(12, 23, 6, 'Так, це нормальна реакція. Почервоніння має пройти через 2-3 дні. Використовуйте заспокійливий крем.', 1, '2026-05-02 14:30:00'),
(13, 43, 24, 'Дякую за процедуру! Результат чудовий!', 1, '2026-05-03 09:00:00'),
(14, 24, 43, 'Дякую за відгук! Завжди рада допомогти!', 0, '2026-05-03 10:00:00'),
(15, 44, 25, 'Підкажіть, через скільки днів можна робити макіяж після пілінгу?', 1, '2026-05-03 06:00:00'),
(16, 25, 44, 'Рекомендую утриматися 3-5 днів. Обов\'язково використовуйте сонцезахисний крем.', 0, '2026-05-03 07:00:00'),
(17, 45, 26, 'Чи можна приходити на процедуру з макіяжем?', 1, '2026-05-03 05:30:00'),
(18, 26, 45, 'Бажано приходити без макіяжу. Це забезпечить кращий результат.', 0, '2026-05-03 06:15:00'),
(19, 46, 22, 'Перший раз до вас. Чи потрібно щось брати з собою?', 1, '2026-05-03 10:30:00'),
(20, 22, 46, 'Достатньо мати з собою гарний настрій. Все інше ми надаємо.', 0, '2026-05-03 11:00:00'),
(21, 22, 23, 'Нагадування: завтра у вас заплановано 5 процедур.', 1, '2026-05-02 15:00:00'),
(22, 22, 24, 'Будь ласка, підтвердьте свій графік на наступний тиждень.', 1, '2026-05-02 15:00:00'),
(23, 22, 25, 'На завтра перенесено одну процедуру на 15:00.', 0, '2026-05-03 05:00:00'),
(24, 23, 22, 'Мені потрібен вихідний 15 травня. Можна?', 1, '2026-05-01 09:00:00'),
(25, 22, 23, 'Так, звісно. Я вас замінив у розкладі.', 1, '2026-05-01 10:00:00'),
(26, 12, 42, 'Як тобі процедура? Рекомендуєш?', 1, '2026-05-03 07:00:00'),
(27, 42, 12, 'Дуже сподобалось! Результат помітний вже після першого разу.', 0, '2026-05-03 08:00:00'),
(28, 47, 22, 'Хочу залишити пропозицію: зробіть каву-брейк для клієнтів.', 1, '2026-05-02 06:00:00'),
(29, 22, 47, 'Дякую за пропозицію! Обов\'язково розглянемо.', 0, '2026-05-03 07:30:00'),
(30, 48, 22, 'Дякую за знижку на день народження! Дуже приємно!', 1, '2026-05-01 12:00:00'),
(31, 22, 48, 'Вітаємо! Приходьте, будемо раді вас бачити!', 0, '2026-05-02 06:00:00');
INSERT INTO `notifications` (`id`, `user_id`, `title`, `message`, `type`, `is_read`, `created_at`) VALUES
(35, 12, 'Нагадування про запис', 'Нагадуємо, що завтра о 10:00 у вас запланована процедура \"Лазерна епіляція\".', 'reminder', 1, '2026-04-26 06:00:00'),
(36, 12, 'Підтвердження запису', 'Ваш запис на 27.04.2026 о 10:00 підтверджено.', 'info', 1, '2026-04-25 11:30:00'),
(37, 12, 'Акція', 'Знижка 20% на фотоомолодження! Діє до 31.05.2026.', 'promotion', 0, '2026-05-01 07:00:00'),
(38, 12, 'Вітання', 'Вітаємо з Днем народження! Подарунок - знижка 15% на будь-яку процедуру.', 'promotion', 0, '2026-05-02 21:00:00'),
(39, 11, 'Підтвердження запису', 'Ваш запис на 27.04.2026 о 11:00 підтверджено.', 'info', 1, '2026-04-25 12:00:00'),
(40, 11, 'Нагадування', 'Завтра о 11:00 у вас процедура. Не забудьте прийти за 5 хвилин.', 'reminder', 1, '2026-04-26 07:00:00'),
(41, 11, 'Нова послуга', 'У нас з\'явилась нова послуга - кріоліполіз! Деталі на сайті.', 'info', 0, '2026-05-02 09:00:00'),
(42, 6, 'Нагадування', 'Нагадуємо, що у вас є 500 бонусних балів, які скоро згоряють.', 'warning', 1, '2026-04-28 06:00:00'),
(43, 6, 'Акція', 'Бонусна програма: подвійні бали за всі процедури в травні!', 'promotion', 0, '2026-05-01 05:00:00'),
(44, 42, 'Підтвердження запису', 'Ваш запис на 01.05.2026 о 10:00 підтверджено.', 'info', 1, '2026-04-30 08:00:00'),
(45, 42, 'Нагадування', 'Завтра о 10:00 у вас процедура. Приходьте без макіяжу.', 'reminder', 1, '2026-04-30 15:00:00'),
(46, 42, 'Відгук', 'Будь ласка, залиште відгук про нашу роботу.', 'info', 0, '2026-05-02 07:00:00'),
(47, 43, 'Скасування запису', 'Ваш запис на 02.05.2026 о 14:00 скасовано. Приносимо вибачення.', 'warning', 1, '2026-05-01 13:00:00'),
(48, 43, 'Пропозиція', 'Пропонуємо записатись на іншу дату. Телефонуйте: 098-123-4567.', 'info', 0, '2026-05-02 06:00:00'),
(49, 44, 'Підтвердження запису', 'Ваш запис на 03.05.2026 о 09:00 підтверджено.', 'info', 1, '2026-05-02 07:00:00'),
(50, 44, 'Нагадування про відгук', 'Поділіться враженнями про процедуру в Instagram та отримайте знижку 10% на наступний візит.', 'promotion', 0, '2026-05-03 09:00:00'),
(51, 45, 'Нагадування', 'Завтра о 12:00 у вас процедура. Не забудьте про попередню оплату.', 'reminder', 0, '2026-05-03 06:00:00'),
(52, 46, 'Акція', 'Акція \"Приведи друга\" - отримайте 200 бонусів на рахунок!', 'promotion', 0, '2026-05-01 08:00:00'),
(53, 47, 'Новий рівень', 'Вітаємо! Ви досягли рівня \"Gold\". Вам доступні нові переваги!', 'info', 0, '2026-05-02 11:00:00'),
(54, 48, 'Вітання з реєстрацією', 'Ласкаво просимо до Cosmology Beauty! Ви отримали 100 бонусів за реєстрацію.', 'info', 1, '2026-03-30 08:00:00'),
(55, 23, 'Новий запис', 'Додано новий запис клієнта на 04.05.2026 о 10:00.', 'info', 1, '2026-05-02 12:00:00'),
(56, 23, 'Нагадування', 'Завтра у вас 5 процедур. Перевірте обладнання.', 'reminder', 0, '2026-05-03 05:00:00'),
(57, 24, 'Скасування запису', 'Клієнт скасував запис на 03.05.2026 о 11:00.', 'warning', 1, '2026-05-02 09:00:00'),
(58, 25, 'Новий запис', 'Додано новий запис на 05.05.2026 о 14:00.', 'info', 0, '2026-05-03 06:00:00'),
(59, 22, 'Новий запис', 'Клієнт 12 створив новий запис на 10.05.2026.', 'info', 1, '2026-05-02 07:00:00'),
(60, 22, 'Новий відгук', 'Клієнт 44 залишив новий відгук (5 зірок).', 'info', 1, '2026-05-02 13:00:00'),
(61, 22, 'Технічне обслуговування', 'Нагадування: перевірка лазерного обладнання 10.05.2026.', 'reminder', 0, '2026-05-03 05:00:00'),
(62, 26, 'Новий відгук', 'Клієнт 45 залишив відгук про вашу роботу: \"Чудовий лікар!\".', 'info', 0, '2026-05-03 10:00:00'),
(63, 27, 'Нагадування', 'Ваш графік на наступний тиждень опубліковано.', 'reminder', 0, '2026-05-03 07:00:00'),
(64, 28, 'Акція', 'Спеціальна пропозиція: безкоштовне навчання новим технікам ін\'єкцій!', 'promotion', 0, '2026-05-01 06:00:00'),
(65, 29, 'Технічне обслуговування', 'Лазер потребує калібрування. Заплануйте на найближчі дні.', 'warning', 0, '2026-05-02 08:00:00'),
(66, 30, 'Новий запис', 'Новий клієнт записався на консультацію 06.05.2026.', 'info', 0, '2026-05-03 11:00:00'),
(67, 31, 'Вітання', 'Вітаємо з річницею роботи в нашому салоні!', 'info', 0, '2026-05-01 09:00:00'),
(68, 32, 'Акція', 'Новий сертифікований курс підвищення кваліфікації. Зареєструйтесь до 15.05.', 'promotion', 0, '2026-05-02 07:30:00');
INSERT INTO `patient_notes` (`id`, `patient_id`, `doctor_id`, `appointment_id`, `note`, `created_at`) VALUES
(30, 12, 44, 4, 'Пацієнтка звернулась з проблемою надмірного росту волосся. Проведено лазерну епіляцію верхньої губи та підборіддя. Шкіра чутлива. Рекомендовано зволожуючий крем.', '2026-04-27 07:30:00'),
(31, 12, 44, 5, 'Повторний візит. Пацієнтка відмічає позитивний результат. Волосся стало тоншим. Проведено другу процедуру лазерної епіляції.', '2026-05-04 08:00:00'),
(32, 12, 44, NULL, 'Пацієнтка пройшла 3 процедури. Результат відмінний. Волосся майже не росте. Рекомендовано закріплюючу процедуру через 2 місяці.', '2026-05-18 07:00:00'),
(33, 12, 45, NULL, 'Консультація з приводу контурної пластики губ. Пацієнтка хоче збільшити об\'єм. Рекомендовано 1 мл філера.', '2026-04-20 12:00:00'),
(34, 43, 45, NULL, 'Проведено процедуру контурної пластики губ філером 1 мл. Результат пацієнта задовольнив. Попереджено про можливий набряк.', '2026-05-02 12:30:00'),
(35, 43, 45, NULL, 'Контрольний огляд через 2 тижні. Набряк спав, результат природний. Пацієнт задоволений.', '2026-05-16 11:00:00'),
(36, 11, 45, NULL, 'Консультація щодо корекції носогубних складок. Рекомендовано 2 мл філера.', '2026-05-10 09:00:00'),
(37, 44, 46, NULL, 'Проведено хімічний пілінг обличчя. Шкіра жирна, схильна до акне. Рекомендовано домашній догляд.', '2026-05-03 07:30:00'),
(38, 44, 46, NULL, 'Контрольний огляд після пілінгу. Шкіра оновлюється, почервоніння зменшилось. Рекомендовано повтор через місяць.', '2026-05-10 08:00:00'),
(39, 44, 46, NULL, 'Проведено чищення обличчя. Шкіра значно чистіша. Пацієнтка задоволена.', '2026-05-17 06:30:00'),
(40, 45, 46, NULL, 'Масаж обличчя для розслаблення м\'язів. Пацієнт відмічає покращення тонусу шкіри.', '2026-05-08 12:00:00'),
(41, 45, 47, NULL, 'Діагностовано акне легкого ступеня. Призначено лікувальну косметику. Рекомендовано чистку обличчя.', '2026-05-04 10:00:00'),
(42, 45, 47, NULL, 'Пацієнт відмічає покращення. Висипань стало менше. Проведено механічну чистку.', '2026-05-11 11:00:00'),
(43, 46, 47, NULL, 'Дерматоскопія родимки на спині. Доброякісна. Рекомендовано спостерігати.', '2026-05-09 08:30:00'),
(44, 46, 48, NULL, 'Пацієнтка скаржиться на випадіння волосся. Проведено трихоскопію. Виявлено ознаки андрогенетичної алопеції.', '2026-05-05 08:00:00'),
(45, 46, 48, NULL, 'Призначено лікування: мезотерапія шкіри голови курсом 6 процедур.', '2026-05-12 07:30:00'),
(46, 46, 48, NULL, 'Проведено першу процедуру мезотерапії. Пацієнтка перенесла добре.', '2026-05-19 08:00:00'),
(47, 47, 49, NULL, 'Консультація з приводу мезотерапії обличчя. Рекомендовано курс з 4 процедур.', '2026-04-25 07:00:00'),
(48, 47, 49, NULL, 'Проведено мезотерапію обличчя коктейлем з гіалуроновою кислотою. Без ускладнень.', '2026-05-06 09:00:00'),
(49, 48, 50, NULL, 'Проведено лазерну епіляцію зони бікіні. Пацієнтка перенесла добре. Шкіра без подразнення.', '2026-05-07 07:30:00'),
(50, 48, 50, NULL, 'Повторна процедура. Волосся стало значно тоншим.', '2026-05-21 06:00:00'),
(51, 42, 51, NULL, 'Діагностика родимок. Всі утворення доброякісні. Рекомендовано УФ-захист.', '2026-04-28 11:00:00'),
(52, 43, 51, NULL, 'Видалення папіломи на шиї. Післяопераційний період без ускладнень.', '2026-05-13 06:30:00'),
(53, 11, 52, NULL, 'Проведено чищення обличчя та масаж. Шкіра зволожена, тон вирівнявся.', '2026-05-15 10:00:00'),
(54, 11, 52, NULL, 'Пацієнтка задоволена результатом. Рекомендовано повтор через 2 тижні.', '2026-05-22 11:30:00'),
(55, 21, 53, NULL, 'Проведено контурну пластику обличчя. Пацієнтка задоволена результатом.', '2026-05-03 08:30:00'),
(56, 21, 53, NULL, 'Контрольний огляд. Набряк минув, результат відмінний. Рекомендовано підтримуючу процедуру через 6 місяців.', '2026-05-10 09:00:00'),
(57, 42, 53, NULL, 'Консультація щодо блефаропластики. Пацієнтці рекомендовано хірургічне втручання.', '2026-05-20 12:00:00');
