INSERT INTO `reviews` (`id`, `client_id`, `appointment_id`, `doctor_id`, `rating`, `comment`, `is_approved`, `created_at`, `doctor_response`, `response_date`) VALUES
(26, 12, 4, 44, 5, 'Чудовий лікар! Дуже задоволена процедурою. Все пройшло безболісно та професійно. Рекомендую!', 1, '2026-04-27 11:00:00', 'Дякую за відгук! Рада, що вам сподобалось. Чекаю на наступний візит!', '2026-04-28 07:00:00'),
(27, 12, 5, 44, 5, 'Вдруге роблю лазерну епіляцію у цього лікаря. Результат чудовий, волосся майже не росте. Дякую!', 1, '2026-05-04 12:00:00', 'Дякую за довіру! Будемо працювати далі для досягнення найкращого результату.', '2026-05-05 06:00:00'),
(28, 42, NULL, 44, 5, 'Дуже професійний підхід. Лікар все детально пояснила, розвіяла всі страхи. Рекомендую однозначно!', 1, '2026-05-02 09:00:00', NULL, NULL),
(29, 6, NULL, 44, 5, 'Перший раз робив лазерну епіляцію. Спочатку хвилювався, але лікар заспокоїла. Все пройшло добре!', 1, '2026-05-10 08:00:00', NULL, NULL),
(30, 12, NULL, 45, 5, 'Найкращий пластичний хірург! Зробила контурну пластику губ – результат перевершив очікування.', 1, '2026-04-21 13:00:00', 'Дякую за високу оцінку! Завжди радий вас бачити.', '2026-04-22 08:00:00'),
(31, 43, NULL, 45, 4, 'Процедура контурної пластики пройшла добре, але був невеликий набряк перші 2 дні. Загалом задоволений результатом.', 1, '2026-05-03 11:30:00', 'Дякую за відгук! Набряк - це нормальна реакція. Радий, що результат вам сподобався.', '2026-05-04 06:00:00'),
(32, 11, NULL, 45, 5, 'Неймовірний результат! Дуже задоволена консультацією та процедурою. Дякую за професіоналізм!', 1, '2026-05-11 10:00:00', 'Дуже приємно чути такі слова! Чекаю вас знову.', '2026-05-12 06:30:00'),
(33, 21, NULL, 45, 5, 'Процедуру контурної пластики не відчула зовсім. Результат чудовий! Дякую лікарю!', 1, '2026-05-20 12:00:00', NULL, NULL),
(34, 44, NULL, 46, 5, 'Пілінг обличчя - шкіра сяє! Лікар дуже уважна та турботлива. Дякую!', 1, '2026-05-03 13:00:00', 'Дякую за відгук! Рада, що процедура принесла задоволення.', '2026-05-04 07:00:00'),
(35, 44, NULL, 46, 5, 'Чудовий майстер! Чищення обличчя проведено ідеально. Шкіра дихає. Рекомендую всім!', 1, '2026-05-18 08:00:00', 'Дякую! Дуже приємно отримувати такий зворотній зв\'язок.', '2026-05-19 11:00:00'),
(36, 45, NULL, 46, 4, 'Масаж обличчя – дуже розслабляючий і приємний. Трохи дорого, але воно того варте.', 1, '2026-05-09 13:30:00', 'Дякую за відгук! Постараємось зробити ціни більш доступними.', '2026-05-10 09:00:00'),
(37, 45, NULL, 47, 5, 'Лікування акне допомогло дуже швидко! Особлива подяка за рекомендації по домашньому догляду.', 1, '2026-05-05 14:00:00', 'Дуже радий, що зміг допомогти! Головне - дотримуватись рекомендацій.', '2026-05-06 08:00:00'),
(38, 46, NULL, 47, 5, 'Дерматоскопія виявилась дуже інформативною. Лікар все детально розповів. Дякую!', 1, '2026-05-10 09:30:00', NULL, NULL),
(39, 46, NULL, 48, 5, 'Трихолог – дуже рідкісний спеціаліст. Лікар допомогла з проблемою випадіння волосся. Дякую величезне!', 1, '2026-05-06 12:00:00', 'Дякую за довіру! Головне - вчасно звернутись. Чекаю на повторний візит.', '2026-05-07 07:00:00'),
(40, 46, NULL, 48, 5, 'Мезотерапія шкіри голови. Вже після першої процедури результат помітний. Рекомендую!', 1, '2026-05-20 10:00:00', NULL, NULL),
(41, 47, NULL, 49, 5, 'Мезотерапія обличчя – це щось неймовірне! Шкіра вирівнялась, зникли дрібні зморшки. Дякую!', 1, '2026-05-07 11:00:00', 'Дуже радий, що процедура вам сподобалась! Звертайтесь ще.', '2026-05-08 06:00:00'),
(42, 47, NULL, 49, 5, 'Відмінний лікар! Все професійно, чисто, комфортно. Рекомендую!', 1, '2026-05-17 08:00:00', NULL, NULL),
(43, 48, NULL, 50, 4, 'Лазерна епіляція пройшла добре, але трохи болісно. Результатом задоволена.', 1, '2026-05-08 13:30:00', 'Дякую за відгук! Наступного разу знеболимо більше.', '2026-05-09 09:00:00'),
(44, 48, NULL, 50, 5, 'Вже 4 процедуру роблю у цього лікаря. Волосся майже зникло. Дуже задоволена!', 1, '2026-05-22 07:00:00', NULL, NULL),
(45, 42, NULL, 51, 5, 'Дуже уважний лікар-дерматолог. Діагностика пройшла швидко і безболісно. Дякую!', 1, '2026-04-29 12:00:00', 'Дякую за відгук! Будьте здорові!', '2026-04-30 07:00:00'),
(46, 43, NULL, 51, 5, 'Видалення папіломи на шиї. Все пройшло ідеально, слідів не залишилось. Рекомендую!', 1, '2026-05-14 09:00:00', NULL, NULL),
(47, 11, NULL, 52, 5, 'Чищення обличчя + масаж – це бомба! Шкіра оновлена, свіжа, сяє. Дуже дякую Аліні!', 1, '2026-05-16 11:00:00', 'Дуже приємно! Приходьте ще, будемо раді)', '2026-05-17 07:00:00'),
(48, 11, NULL, 52, 5, 'Регулярно ходжу до Аліни на процедури. Найкращий косметолог у місті!', 1, '2026-05-23 08:00:00', NULL, NULL),
(49, 21, NULL, 53, 5, 'Пластичний хірург з золотими руками! Контурна пластика пройшла ідеально. Дякую за красу!', 1, '2026-05-04 13:00:00', 'Дуже дякую за теплі слова! Головне, що ви задоволені результатом!', '2026-05-05 08:00:00'),
(50, 42, NULL, 53, 5, 'Консультація була дуже професійною. Лікар відповів на всі питання. Рекомендую!', 1, '2026-05-21 11:00:00', NULL, NULL),
(51, 12, 444, 45, 5, ':) Все сподобалося', 1, '2026-05-07 21:48:20', NULL, NULL);
