INSERT INTO `specializations` (`id`, `name`, `description`) VALUES
(1, 'Лазерна косметологія', 'Використання лазерних технологій для лікування шкіри, видалення волосся, судин та пігментації. Включає лазерну епіляцію, лазерне омолодження, видалення татуювань.'),
(2, 'Ін\'єкційна косметологія', 'Проведення ін\'єкційних процедур: мезотерапія, біоревіталізація, контурна пластика, ботулінотерапія. Корекція вікових змін та моделювання обличчя.'),
(3, 'Дерматовенерологія', 'Діагностика та лікування захворювань шкіри, волосся, нігтів. Лікування акне, дерматитів, псоріазу, грибкових захворювань.'),
(4, 'Дерматоскопія', 'Діагностика новоутворень шкіри за допомогою дерматоскопа. Виявлення раку шкіри на ранніх стадіях, контроль родимок.'),
(5, 'Трихологія', 'Лікування захворювань волосся та шкіри голови. Боротьба з випадінням волосся, облисінням, лупою, себореєю.'),
(6, 'Пластична хірургія', 'Проведення хірургічних втручань для корекції зовнішності: блефаропластика, ринопластика, ліпосакція, мамотопластика, абдомінопластика.'),
(7, 'Естетична косметологія', 'Проведення доглядових процедур: чистки обличчя, пілінги, масажі, маски. Підбір домашнього догляду та косметики.'),
(8, 'Апаратна косметологія', 'Використання апаратних методик: RF-ліфтинг, ультразвукова чистка, мікрострумова терапія, фотоомолодження, кріоліполіз.'),
(9, 'Масаж та тілесні практики', 'Проведення лікувального, релаксуючого, моделюючого масажу обличчя та тіла. Пресотерапія, вакуумний масаж.'),
(10, 'Онкодерматологія', 'Діагностика та лікування онкологічних захворювань шкіри. Видалення новоутворень з гістологічним дослідженням.'),
(11, 'Педіатрична дерматологія', 'Лікування шкірних захворювань у дітей: атопічний дерматит, алергічні висипи, вугровий висип у підлітків.'),
(12, 'Косметологія повік', 'Спеціалізація на догляді за шкірою навколо очей. Ламінування вій, фарбування вій та брів, корекція брів.'),
(13, 'Лімфодренаж та детокс', 'Процедури для виведення зайвої рідини, зменшення набряків, покращення лімфотоку. Лімфодренажний масаж, пресотерапія.'),
(14, 'Anti-age терапія', 'Комплексні програми омолодження шкіри. Поєднання ін\'єкційних, апаратних та доглядових методик для боротьби з віковими змінами.'),
(15, 'Корекція рубців та постакне', 'Лікування атрофічних та гіпертрофічних рубців, постакне. Використання лазерної шліфовки, пілінгів, мезотерапії.');
